package ro.leo.visual;
import ro.leo.i18n.L;
import android.app.*;import android.content.*;import android.database.Cursor;import android.os.*;import android.provider.*;import android.text.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;

/** On-demand, bounded local search. No persistent index or background service. */
public final class GlobalSearchActivity extends LeoActivity {
 static final class Hit {final String label;final Intent intent;Hit(String s,Intent i){label=s;intent=i;}}
 private EditText query;private ListView results;private final Handler handler=new Handler();private int generation;
 private final Runnable search=new Runnable(){public void run(){find();}};
 static boolean matches(String value,String query){return (query.matches("[0-9]+")&&ContactKeys.matches(value==null?"":value,"",query))||fold(value).contains(fold(query));}
 private static String fold(String s){return java.text.Normalizer.normalize(s==null?"":s,java.text.Normalizer.Form.NFD).replaceAll("\\p{M}","").toLowerCase(Locale.ROOT);}
 protected void onCreate(Bundle b){super.onCreate(b);begin(L.t("Caută în Leo"));query=new EditText(this);query.setSingleLine(true);query.setTextColor(android.graphics.Color.WHITE);query.setHintTextColor(0xffaaaaaa);query.setHint(L.t("Aplicații, contacte, notițe, muzică"));query.setInputType(InputType.TYPE_CLASS_TEXT);query.setFilters(new InputFilter[]{new InputFilter.LengthFilter(80)});root.addView(query);results=new ListView(this);root.addView(results,new LinearLayout.LayoutParams(-1,0,1));footer(L.t("Caută"),L.t("Rezultate ↓"),L.t("Șterge"));left=new Runnable(){public void run(){find();results.requestFocus();}};query.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){++generation;handler.removeCallbacks(search);handler.postDelayed(search,250);}public void afterTextChanged(Editable e){}});query.setText(getIntent().getStringExtra("query"));query.setOnKeyListener(new View.OnKeyListener(){public boolean onKey(View v,int k,KeyEvent e){if(k==KeyEvent.KEYCODE_DPAD_DOWN&&e.getAction()==0){results.requestFocus();return true;}return false;}});find();query.requestFocus();}
 protected void onPause(){handler.removeCallbacks(search);++generation;super.onPause();}protected void onDestroy(){handler.removeCallbacksAndMessages(null);super.onDestroy();}
 private void find(){final String term=query.getText().toString().trim();final int token=++generation;worker.execute(new Runnable(){public void run(){final ArrayList<Hit> hits=collect(GlobalSearchActivity.this,term);ui(new Runnable(){public void run(){if(token!=generation||isFinishing())return;ArrayList<String> labels=new ArrayList<String>();for(Hit h:hits)labels.add(h.label);if(labels.isEmpty())labels.add(term.isEmpty()?L.t("Scrie pentru a căuta local"):L.t("Niciun rezultat · limite locale"));results.setAdapter(new ArrayAdapter<String>(GlobalSearchActivity.this,android.R.layout.simple_list_item_1,labels){public View getView(int p,View v,android.view.ViewGroup parent){TextView t=(TextView)super.getView(p,v,parent);t.setTextColor(android.graphics.Color.WHITE);t.setTextSize(16);return t;}});results.setOnItemClickListener(new AdapterView.OnItemClickListener(){public void onItemClick(AdapterView<?> a,View v,int i,long id){if(i<hits.size())try{startActivity(hits.get(i).intent);}catch(RuntimeException e){notice(L.t("Rezultat indisponibil"));}}});}});}});}
 static ArrayList<Hit> collect(Context c,String term){ArrayList<Hit> found=new ArrayList<Hit>();if(term.isEmpty())return found;
  for(int i=0;i<AppCatalog.NAMES.length&&found.size()<20;i++)if(matches(AppCatalog.NAMES[i],term))found.add(new Hit(L.t("Aplicație · ")+AppCatalog.NAMES[i],new Intent(c,MainActivity.class).putExtra("open_app",i).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP)));
  try(Cursor rows=c.getContentResolver().query(ContactsContract.CommonDataKinds.Phone.CONTENT_URI,new String[]{"contact_id","display_name","data1"},null,null,"display_name COLLATE LOCALIZED ASC")){HashSet<Long> ids=new HashSet<Long>();int scanned=0,n=0;while(rows!=null&&rows.moveToNext()&&scanned++<2000&&n<20)if((matches(rows.getString(1),term)||matches(rows.getString(2),term))&&ids.add(rows.getLong(0))){found.add(new Hit(L.t("Contact · ")+rows.getString(1),new Intent(c,ContactsActivity.class).putExtra("contact_id",rows.getLong(0))));n++;}}catch(RuntimeException ignored){}
  try{File f=new File(c.getFilesDir(),"notes.json");if(BackupEngine.atomicExists(f)){JSONArray notes=new JSONArray(new String(BackupEngine.atomicBytes(f,1024*1024),"UTF-8"));int n=0;for(int i=0;i<notes.length()&&n<20;i++){JSONObject note=notes.getJSONObject(i);String body=note.getString("body");if(matches(body,term)){found.add(new Hit(L.t("Notiță · ")+body.replace('\n',' ').substring(0,Math.min(body.length(),60)),new Intent(c,NotesActivity.class).putExtra("note_id",note.getString("id"))));n++;}}}}catch(Exception ignored){}
  try(Cursor rows=c.getContentResolver().query(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,new String[]{"_id","title","artist"},null,null,"title COLLATE NOCASE ASC")){int scanned=0,n=0;while(rows!=null&&rows.moveToNext()&&scanned++<2000&&n<20)if(matches(rows.getString(1),term)||matches(rows.getString(2),term)){found.add(new Hit(L.t("Muzică · ")+rows.getString(1),new Intent(c,MediaActivity.class).setData(ContentUris.withAppendedId(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,rows.getLong(0)))));n++;}}catch(RuntimeException ignored){}return found;
 }
}
